public static class GameUtil{public static float RateConvert(float a,float b,float c,float d,float e,bool f){return a;}public static int RateConvert(int a,int b,int c,int d,int e,bool f){return a;}}
public class Fixture{public float distance;public float axisA,axisB;public int previous,current;public bool Run(){int slidingRate=1;float num=distance;int a;int b;int c;if(num<30f||num>=70f){return false;}float first=axisA;float second=axisB;if(first*second==0f){return false;}float dot=(first+second)/(first*second);a=(int)GameUtil.RateConvert(dot,0f,-1f,0f,100f,true);b=0;int oldValue=previous;int newValue=current;c=GameUtil.RateConvert(newValue-oldValue,20,0,0,100,true);int final=(int)((0.6f*(float)a+0.2f*(float)b+0.3f*(float)c)/1.1f);return final>50;}}
